// Writes public/bladefall-climb-together-rooms.js from scripts/together/rooms.mjs and the proven two-track routes
// in scripts/together/routes.json (run scripts/together/prove.mjs first).
import {readFileSync,writeFileSync} from 'node:fs';
import {rooms} from './rooms.mjs';
const routes=JSON.parse(readFileSync(new URL('./routes.json',import.meta.url)));
const list=rooms();for(const r of list)if(!routes[r.id])throw Error('No proven route for '+r.id+': run scripts/together/prove.mjs');
writeFileSync(new URL('../../public/bladefall-climb-together-rooms.js',import.meta.url),
 '/* Generated by scripts/together/build.mjs: the Ascend Together rooms and their proven two-knight routes. */\n'+
 '(function(root){\'use strict\';root.BladefallClimbTogetherRooms=Object.freeze({rooms:'+JSON.stringify(list)+',routes:'+JSON.stringify(routes)+'});})(typeof globalThis!==\'undefined\'?globalThis:window);\n');
console.log('wrote',list.length,'rooms');
